        switch (message.payload.type) {
          case 'RESET':
            setStateFromDevtools(initialState)
            return extension.init(api.getState())

          case 'COMMIT':
            return extension.init(api.getState())

          case 'ROLLBACK':
            return parseJsonThen<S>(message.state, (state) => {
              setStateFromDevtools(state)
